  "哎":{"py":"āi","t":1,"senses":["hey, oh — an exclamation of surprise or mild dismay"],"sound":["Starts straight on the vowel, with no consonant.","-ai : “eye”.","Tone 1 — high and flat, held level near the top of your range."],"words":[{"hz":"哎呀","py":"āiyā","en":"oh no!, oh dear!","mine":true}],"sents":[{"hz":"哎呀，太贵了。","py":"Āiyā, tài guì le.","en":"Oh no, that's too expensive."}]},
