  "哦":{"py":"ó","t":2,"senses":["oh — marks that something just clicked"],"sound":["Starts straight on the vowel, with no consonant.","-o : a rounded “aw”.","Tone 2 — rising, like the end of an English question."],"words":[],"sents":[{"hz":"哦，我明白了。","py":"Ó, wǒ míngbai le.","en":"Oh, I get it now."}]},
  "哪":{"py":"nǎr","t":3,"senses":["which","where (in 哪儿 and 哪里)"],"sound":["n- : as in English “no”.","Tone 3 — dips low then rises; in running speech it often just stays low."],"words":[{"hz":"哪儿","py":"nǎr","en":"where","mine":true},{"hz":"哪个","py":"nǎge","en":"which","mine":true}],"sents":[{"hz":"你在哪儿？","py":"Nǐ zài nǎr?","en":"Where are you?"}]},
