  "啊":{"py":"a","t":5,"senses":["adds feeling — surprise, emphasis, warmth"],"sound":["Starts straight on the vowel, with no consonant.","-a : “ah”, as in “father”.","Neutral tone — short and light, with no tone of its own."],"words":[{"hz":"好啊","py":"hǎo a","en":"sure!"}],"sents":[{"hz":"好啊，我们一起去。","py":"Hǎo a, wǒmen yìqǐ qù.","en":"Sure, let's go together."}]},
  "啡":{"py":"fēi","t":1,"senses":["no meaning of its own — it is there for the sound, in 咖啡 (coffee)"],"sound":["f- : as in English “fun”.","-ei : “ay”, as in “day”.","Tone 1 — high and flat, held level near the top of your range."],"words":[{"hz":"咖啡","py":"kāfēi","en":"coffee","mine":true},{"hz":"喝咖啡","py":"hē kāfēi","en":"drink coffee","mine":true}],"sents":[{"hz":"这个咖啡很好喝。","py":"Zhège kāfēi hěn hǎohē.","en":"This coffee is good."}]},
