  "家":{"py":"jiā","t":1,"senses":["home, family","specialist, -ist (suffix)","measure word for businesses"],"sound":["j- : like the j in “jeep”, but the tongue lies flat with its tip behind your bottom teeth.","-ia : “yah”.","Tone 1 — high and flat, held level near the top of your range."],"words":[{"hz":"家教","py":"jiājiào","en":"tutor","mine":true},{"hz":"家人","py":"jiārén","en":"family members","mine":true},{"hz":"回家","py":"huí jiā","en":"to go home, to visit home","mine":true},{"hz":"专家","py":"zhuānjiā","en":"expert"}],"sents":[{"hz":"我的家教是中国人。","py":"Wǒ de jiājiào shì Zhōngguórén.","en":"My tutor is Chinese."}]},
