  "式":{"py":"shì","t":4,"senses":["a style, a type","a formula, a pattern"],"sound":["sh- : like the sh in “shirt”, tongue curled up and back.","-i here is not “ee”. Hold the consonant and add a buzz — almost no vowel at all.","Tone 4 — a sharp fall from high to low, like a firm command."],"words":[{"hz":"美式","py":"měishì","en":"American-style"},{"hz":"方式","py":"fāngshì","en":"a way of doing"}],"sents":[{"hz":"美式橄榄球","py":"měishì gǎnlǎnqiú","en":"American football","mine":true},{"hz":"我喜欢看体育比赛，特别是篮球和美式橄榄球。","py":"wǒ xǐhuan kàn tǐyù bǐsài, tèbié shì lánqiú hé měishì gǎnlǎnqiú.","en":"I like watching sports, especially basketball and football.","mine":true}]},
  "弟":{"py":"dì","t":4,"senses":["younger brother"],"sound":["d- : no puff of air — closer to the t in “stop” than the d in “dog”.","-i : “ee”, as in “see”.","Tone 4 — a sharp fall from high to low, like a firm command."],"words":[{"hz":"兄弟姐妹","py":"xiōngdì jiěmèi","en":"siblings","mine":true},{"hz":"弟弟","py":"dìdi","en":"younger brother"},{"hz":"兄弟","py":"xiōngdì","en":"brothers"}],"sents":[{"hz":"我弟弟在上高中。","py":"Wǒ dìdi zài shàng gāozhōng.","en":"My younger brother is in high school."}]},
  "张":{"py":"zhāng","t":1,"senses":["measure word for flat things — paper, tickets, tables","to open, to stretch out","a very common surname"],"sound":["zh- : like the j in “job”, with the tongue tip curled up and back.","-ang : “ahng”.","Tone 1 — high and flat, held level near the top of your range."],"words":[{"hz":"我很紧张","py":"wǒ hěn jǐnzhāng","en":"I'm nervous","mine":true},{"hz":"一张票","py":"yì zhāng piào","en":"one ticket"}],"sents":[{"hz":"我有两张票。","py":"Wǒ yǒu liǎng zhāng piào.","en":"I have two tickets."}]},
  "弱":{"py":"ruò","t":4,"senses":["weak, feeble"],"sound":["r- : tongue curled back like zh/ch/sh, then buzzed — between an English r and the s in “measure”.","-uo : “waw”.","Tone 4 — a sharp fall from high to low, like a firm command."],"words":[{"hz":"我很虚弱","py":"wǒ hěn xūruò","en":"I'm weak","mine":true},{"hz":"虚弱","py":"xūruò","en":"weak, frail"}],"sents":[{"hz":"我今天很虚弱。","py":"Wǒ jīntiān hěn xūruò.","en":"I feel weak today."}]},
  "强":{"py":"qiáng","t":2,"senses":["strong, powerful","to force"],"sound":["q- : like the ch in “cheap”, same flat tongue as j. Never a k sound.","-iang : “yahng”.","Tone 2 — rising, like the end of an English question."],"words":[{"hz":"我很强壮","py":"wǒ hěn qiángzhuàng","en":"I'm strong","mine":true},{"hz":"强壮","py":"qiángzhuàng","en":"strong"}],"sents":[{"hz":"我想变强。","py":"Wǒ xiǎng biàn qiáng.","en":"I want to get stronger."}]},
  "当":{"py":"dāng","t":1,"senses":["at the time of, when","to serve as, to work as","to face, to bear"],"sound":["d- : no puff of air — closer to the t in “stop” than the d in “dog”.","-ang : “ahng”.","Tone 1 — high and flat, held level near the top of your range."],"words":[{"hz":"当时","py":"dāngshí","en":"at that time","mine":true},{"hz":"当然","py":"dāngrán","en":"of course"}],"sents":[{"hz":"当时我还是学生。","py":"Dāngshí wǒ háishi xuésheng.","en":"I was still a student back then."}]},
  "影":{"py":"yǐng","t":3,"senses":["a shadow","a film, a movie (in 电影)"],"sound":["The y-/w- at the front is a spelling device, not a separate consonant sound.","Starts straight on the vowel, with no consonant.","-ing : as in English “sing”.","Tone 3 — dips low then rises; in running speech it often just stays low."],"words":[{"hz":"电影","py":"diànyǐng","en":"movie"}],"sents":[{"hz":"我喜欢看电影。","py":"wǒ xǐhuan kàn diànyǐng.","en":"I like to watch movies.","mine":true}]},
  "很":{"py":"hěn","t":3,"senses":["very","often just links an adjective to its subject, with little force of its own"],"sound":["h- : raspier than English h, with friction at the back of the throat.","-en : “un”, as in “fun”.","Tone 3 — dips low then rises; in running speech it often just stays low."],"words":[{"hz":"我很紧张","py":"wǒ hěn jǐnzhāng","en":"I'm nervous","mine":true},{"hz":"我很忙","py":"wǒ hěn máng","en":"I'm busy","mine":true},{"hz":"我很开心","py":"wǒ hěn kāixīn","en":"I'm happy","mine":true},{"hz":"我很冷","py":"wǒ hěn lěng","en":"I'm cold","mine":true},{"hz":"我很热","py":"wǒ hěn rè","en":"I'm hot","mine":true},{"hz":"我很无聊","py":"wǒ hěn wúliáo","en":"I'm bored","mine":true},{"hz":"很好","py":"hěn hǎo","en":"very good"},{"hz":"很少","py":"hěn shǎo","en":"rarely"}],"sents":[{"hz":"今天很忙。","py":"Jīntiān hěn máng.","en":"Today is busy."},{"hz":"很高兴认识你","py":"hěn gāoxìng rènshi nǐ","en":"nice to meet you","mine":true},{"hz":"这个很容易","py":"zhège hěn róngyì","en":"this is easy","mine":true},{"hz":"这个菜很好吃","py":"zhège cài hěn hǎochī","en":"this dish is delicious","mine":true}]},
  "律":{"py":"lǜ","t":4,"senses":["law, statute","rhythm, rule"],"sound":["l- : as in English “learn”.","-ü : say “ee” with your lips rounded as if for “oo”. Written plain u after j, q, x and y.","Tone 4 — a sharp fall from high to low, like a firm command."],"words":[{"hz":"律师","py":"lǜshī","en":"lawyer","mine":true},{"hz":"法律","py":"fǎlǜ","en":"law"}],"sents":[{"hz":"我朋友是律师。","py":"Wǒ péngyou shì lǜshī.","en":"My friend is a lawyer."}]},
  "得":{"py":"de","t":5,"senses":["links a verb to a description of how it's done — 吃得多 'eats a lot'"],"sound":["d- : no puff of air — closer to the t in “stop” than the d in “dog”.","-e : “uh”, as in “duh”, made further back in the mouth.","Neutral tone — short and light, with no tone of its own."],"words":[{"hz":"觉得","py":"juéde","en":"to feel, to think","mine":true},{"hz":"比…得少","py":"bǐ… de shǎo","en":"comparative — less","mine":true},{"hz":"考得很好","py":"kǎo de hěn hǎo","en":"to ace, to do very well on a test","mine":true},{"hz":"得到","py":"dédào","en":"to obtain"}],"sents":[{"hz":"他中文说得很好。","py":"Tā Zhōngwén shuō de hěn hǎo.","en":"He speaks Chinese very well."},{"hz":"跟…吃得一样多","py":"gēn… chī de yíyàng duō","en":"equative comparison — quantity","mine":true}],"other":"Read dé for 'to get, to obtain'; read děi for 'must, have to'. Three readings, one character."},
