  "所":{"py":"suǒ","t":3,"senses":["place","used with 以 to mean 'therefore'"],"sound":["s- : as in English “see”.","-uo : “waw”.","Tone 3 — dips low then rises; in running speech it often just stays low."],"words":[{"hz":"所以","py":"suǒyǐ","en":"so, therefore","mine":true},{"hz":"厕所","py":"cèsuǒ","en":"toilet"}],"sents":[{"hz":"我很忙，所以不去。","py":"Wǒ hěn máng, suǒyǐ bú qù.","en":"I'm busy, so I'm not going."}]},
